ALTER TABLE public.cash_flow_payables ALTER COLUMN source_order_id DROP NOT NULL; ALTER TABLE public.cash_flow_payables ADD CONSTRAINT cash_flow_payables_origin_required CHECK((source_order_id IS NOT NULL AND spend_line_id IS NULL) OR (source_order_id IS NULL AND spend_line_id IS NOT NULL)); DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.log_cash_flow_payable_change()'::regprocedure) INTO d; d:=replace(d,'''Recebido do myio supply''','CASE WHEN NEW.spend_line_id IS NOT NULL THEN ''Recebido do Spend'' ELSE ''Recebido do myio supply'' END'); EXECUTE d; END $$;